  "atomic_questions": [
    "What distance metric should be used to compute travel distances between the depot and customers (and between customers), for example Euclidean distance, Manhattan distance, or straight-line distance divided by a speed?"
  ],
  "rationale": "The response asks for a single policy choice regarding the distance metric, which constitutes one semantically independent question."
}

